      "why": "The claim compares prices in two years, so it needs inflation figures for both years from a clear source. The unemployment rate is a figure, but it measures the share of the labour force (people working or looking for work) who have no job, not prices, so it does not match the claim.",
      "clue": "Match the figure to the claim, the years and the source."
